// Package fixture builds deterministic Matroska/WebM sample files in memory.
// Nothing here reads external media: every byte of every test sample is
// generated by these builders, which keeps the test suite hermetic and lets
// each damage class be reproduced exactly.
package fixture

import (
	"encoding/binary"
	"fmt"
	"math"
)

// Encoder appends EBML elements to a byte slice.
type Encoder struct {
	buf []byte
}

// NewEncoder returns an empty encoder.
func NewEncoder() *Encoder { return &Encoder{} }

// Bytes returns the accumulated bytes.
func (e *Encoder) Bytes() []byte { return e.buf }

// Len returns the accumulated length.
func (e *Encoder) Len() int { return len(e.buf) }

// Raw appends raw bytes.
func (e *Encoder) Raw(b []byte) *Encoder {
	e.buf = append(e.buf, b...)
	return e
}

// EncID encodes a Matroska element ID into its canonical byte form.
func EncID(id uint32) []byte {
	switch {
	case id > 0x00FFFFFF:
		return []byte{byte(id >> 24), byte(id >> 16), byte(id >> 8), byte(id)}
	case id > 0x0000FFFF:
		return []byte{byte(id >> 16), byte(id >> 8), byte(id)}
	case id > 0x000000FF:
		return []byte{byte(id >> 8), byte(id)}
	default:
		return []byte{byte(id)}
	}
}

// EncSize encodes a data size as a minimal EBML vint.
func EncSize(size uint64) []byte {
	length := 1
	for length < 8 && size >= (uint64(1)<<(7*uint(length)))-1 {
		length++
	}
	buf := make([]byte, length)
	v := size
	for i := length - 1; i >= 0; i-- {
		buf[i] = byte(v)
		v >>= 8
	}
	buf[0] |= byte(0x80) >> (uint(length) - 1)
	return buf
}

// UnknownSize is the one-byte unknown-size marker.
var UnknownSize = []byte{0xFF}

// Header appends an element ID and a known payload size.
func (e *Encoder) Header(id uint32, size int) *Encoder {
	e.buf = append(e.buf, EncID(id)...)
	e.buf = append(e.buf, EncSize(uint64(size))...)
	return e
}

// HeaderUnknown appends an element ID and the unknown-size marker.
func (e *Encoder) HeaderUnknown(id uint32) *Encoder {
	e.buf = append(e.buf, EncID(id)...)
	e.buf = append(e.buf, UnknownSize...)
	return e
}

// Element appends a complete element.
func (e *Encoder) Element(id uint32, payload []byte) *Encoder {
	e.Header(id, len(payload))
	e.buf = append(e.buf, payload...)
	return e
}

// UintElement appends an unsigned integer element with a minimal width.
func (e *Encoder) UintElement(id uint32, v uint64) *Encoder {
	return e.Element(id, EncUint(v))
}

// EncUint encodes an unsigned integer with the minimal byte width (at least 1).
func EncUint(v uint64) []byte {
	if v == 0 {
		return []byte{0}
	}
	var buf [8]byte
	binary.BigEndian.PutUint64(buf[:], v)
	i := 0
	for i < 7 && buf[i] == 0 {
		i++
	}
	return append([]byte(nil), buf[i:]...)
}

// IntElement appends a signed integer element with a minimal width.
func (e *Encoder) IntElement(id uint32, v int64) *Encoder {
	var width int
	switch {
	case v >= -128 && v <= 127:
		width = 1
	case v >= -32768 && v <= 32767:
		width = 2
	default:
		width = 4
	}
	buf := make([]byte, width)
	u := uint64(uint64(v) & (1<<(8*uint(width)) - 1))
	for i := width - 1; i >= 0; i-- {
		buf[i] = byte(u)
		u >>= 8
	}
	return e.Element(id, buf)
}

// StringElement appends a string element.
func (e *Encoder) StringElement(id uint32, s string) *Encoder {
	return e.Element(id, []byte(s))
}

// FloatElement appends a 8-byte IEEE float element.
func (e *Encoder) FloatElement(id uint32, f float64) *Encoder {
	var buf [8]byte
	binary.BigEndian.PutUint64(buf[:], math.Float64bits(f))
	return e.Element(id, buf[:])
}

// Container appends an element whose payload is built by fn.
func (e *Encoder) Container(id uint32, fn func(*Encoder)) *Encoder {
	inner := NewEncoder()
	fn(inner)
	return e.Element(id, inner.Bytes())
}

// UnknownContainer appends an unknown-size element whose payload is fn.
func (e *Encoder) UnknownContainer(id uint32, fn func(*Encoder)) *Encoder {
	e.HeaderUnknown(id)
	fn(e)
	return e
}

// Overwrite replaces bytes at offset. It is used to inject damage into a
// fully built fixture.
func (e *Encoder) Overwrite(offset int, b []byte) {
	copy(e.buf[offset:], b)
}

// PatchSize rewrites the size field at sizeOffset so the element at idOffset
// declares declaredSize. The encoded vint must be the same width; PatchSize
// returns an error otherwise so tests cannot silently shift the layout.
func (e *Encoder) PatchSize(sizeOffset, width int, declaredSize uint64) error {
	enc := EncSize(declaredSize)
	if len(enc) != width {
		return fmt.Errorf("fixture: size %d needs %d bytes, have %d", declaredSize, len(enc), width)
	}
	copy(e.buf[sizeOffset:sizeOffset+width], enc)
	return nil
}

// Find returns the first occurrence of needle, or -1.
func (e *Encoder) Find(needle []byte) int {
	for i := 0; i+len(needle) <= len(e.buf); i++ {
		match := true
		for j := range needle {
			if e.buf[i+j] != needle[j] {
				match = false
				break
			}
		}
		if match {
			return i
		}
	}
	return -1
}

// TrackSpec describes a track to synthesise.
type TrackSpec struct {
	Number       uint64
	Type         uint64 // 1 video, 2 audio, 17 subtitle
	CodecID      string
	CodecPrivate []byte
	Width        uint64
	Height       uint64
	SampleRate   uint64
	Channels     uint64
	Language     string
	DefaultDur   uint64
}

// BlockSpec requests a block at a specific timestamp.
type BlockSpec struct {
	Track uint64
	Tick  int64 // absolute timestamp in Segment ticks
	Data  []byte
	Key   bool
	Laced int // number of frames for fixed lacing; 0 or 1 = no lacing
}

// Layout controls how the document is assembled.
type Layout struct {
	DocType string
	// UnknownSegment writes the Segment with unknown size.
	UnknownSegment bool
	// UnknownCluster writes each Cluster with unknown size.
	UnknownCluster bool
	// ClusterSpan is the number of blocks grouped into one Cluster.
	ClusterSpan int
	// TimestampScale defaults to 1ms.
	TimestampScale uint64
	// NoCues omits the Cues element.
	NoCues bool
	// CuesFirst writes Cues before Clusters (as fast-start files do).
	CuesFirst bool
	// SortByTime orders block specs by timestamp; when false the caller's
	// order (which may be interleaved or out of order) is preserved.
	SortByTime bool
	Duration   float64
}

// Document is a built fixture with useful offsets recorded.
type Document struct {
	Bytes []byte
	// ClusterOffsets lists absolute offsets of each Cluster element.
	ClusterOffsets []int64
	// BlockOffsets lists absolute offsets of each block payload.
	BlockOffsets []int64
	// CueCount is the number of CuePoint entries written.
	CueCount int
	// SegmentSizeOffset and SegmentSizeWidth locate the Segment size vint.
	SegmentSizeOffset int
	SegmentSizeWidth  int
	// SegmentDataOffset is the absolute offset of the Segment payload.
	SegmentDataOffset int64
	// ClusterSizeOffsets lists the size-vint offset and width of each
	// known-size Cluster; entries are {-1,0} for unknown-size Clusters.
	ClusterSizeOffsets [][2]int
	// CuesOffset is the absolute offset of Cues, or -1.
	CuesOffset int64
}
